CREATE DATABASE regional_business_analysis;
USE regional_business_analysis;
create table departments (department_id varchar(10) primary key,department_name varchar(50) not null);
create table regions (region_id varchar(10) primary key, region_name varchar(50) not null,region_manager varchar(50) not null);
create table customers (customer_id varchar(10) primary key ,customer_first_name varchar(50) not null,customer_last_name varchar(50) not null,
customer_email varchar(100) unique not null,customer_city varchar(50) not null ,customer_country varchar(50) not null);
create table categories(category_id varchar(10) primary key,category_name varchar(50) not null,department_id varchar(10) not null,
foreign key (department_id) references departments(department_id));
create table products(product_id varchar(10) primary key,product_name varchar(50) not null,category_id varchar(10) not null,
product_unit_cost decimal(10,2) not null,product_unit_price decimal(10,2) not null,
foreign key (category_id)references categories(category_id));
create table orders(order_id varchar(10) primary key, order_date date not null,customer_id varchar(10) not null,region_id varchar(10) not null,
currency_code varchar(10) not null,order_status varchar(20) not null,shipping_cost decimal(10,2) not null,
discount_amount decimal(10,2) not null ,foreign key (customer_id) references customers(customer_id),
foreign key (region_id) references regions(region_id));
create table order_items(order_item_id varchar(10) primary key,order_id varchar(10) not null,product_id varchar(10) not null,order_quantity int not null,
price_at_sale decimal(10,2) not null,foreign key (order_id) references orders(order_id),foreign key (product_id) references products(product_id));
